  void removeFirstAddedNumber() {
    const int number = q.front();
    q.pop();
    if (--count[number])
      count.erase(number);
    sortedList.erase(sortedList.find(number));
    // Note: No need to update the heap now; we'll clean up stale entries when
    // getting the mode.
    sum -= number;
  }

