    int count = 0;
    int prevEnd = 0;

    Arrays.sort(intervals, Comparator.comparingInt((int[] interval) -> interval[0]));

    for (int[] interval : intervals) {
      final int start = interval[0];
      final int end = interval[1];
      if (start < prevEnd) {
        prevEnd = Math.max(prevEnd, end);
      } else {
        prevEnd = end;
        ++count;
      }
    }

    return count;
  }
}

