      ans %= kMod;

      // count[mode] = 2 -- [? ?] a [a ?]
      ans += rightCount * calc(num, rightOther, leftOther, right, left) % kMod;
      ans %= kMod;

      ++left[num];
    }

    return ans % kMod;
  }

 private:
