    for (int i = 0; i < s.length(); ++i) {
      final int index = s.charAt(i) - 'a';
      final int oppositeIndex = 25 - index;
      if (!indices[oppositeIndex].isEmpty())
        ans += i - indices[oppositeIndex].poll();
