    MedianTracker tracker(k);

    for (int i = 0; i < k; ++i)
      tracker.add(nums[i]);

    long ans = tracker.getCost();

    for (int i = k; i < nums.size(); ++i) {
      tracker.remove(nums[i - k]);
      tracker.add(nums[i]);
      ans = min(ans, tracker.getCost());
    }

    return ans;
  }
};

